+  }).join('');
+
+  let result = apply(protectedText);
+  for (let index = placeholders.length - 1; index >= 0; index--) {
+    const placeholder = `\\uE000LINTER_IGNORE_${[...ignoredLineIndexes][index]}_${index}\\uE001`;
+    result = result.replace(placeholder, placeholders[index].replace(/\
$/, ''));
+  }
+
+  return result;
+}
+
+function getIgnoredLineIndexes(text: string, lines: TextLine[], ruleAlias: string | null, knownRuleAliases: Set<string>): Set<number> {
+  const ignored = new Set<number>();
+  const excludedRanges = getExcludedRanges(text);
+  const scopes: DisableScope[] = [];
+  const normalizedRuleAlias = ruleAlias?.toLowerCase();
