+function parseMarker(line: string, knownRuleAliases: Set<string>): Marker | null {
+  const standaloneComment = line.replace(/\
$/, '').match(/^[\	 ]*(?:<!--([\\s\\S]*?)-->|%%([\\s\\S]*?)%%)[\	 ]*$/);
+  if (!standaloneComment) {
+    return null;
+  }
