+  const content = (standaloneComment[1] ?? standaloneComment[2]).trim();
+  const match = content.match(/^linter-(disable-next-n-lines:\\s*([^\	 ]+)(?:[\	 ]+(.*))?|disable-next-line(?:[\	 ]+(.*))?|disable(?:[\	 ]+(.*))?|enable(?:[\	 ]+(.*))?)$/);
