+
+function normalizeRules(ruleText: string | undefined, knownRuleAliases: Set<string>): string[] | null {
+  if (ruleText === undefined) {
+    return null;
+  }
+  return [...new Set(ruleText.split(',').map((rule) => rule.trim().toLowerCase()).filter((rule) => rule !== '' && knownRuleAliases.has(rule)))];
